package com.sbcs.detect.dungeon;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * The reel's filler - {@code assets/sbcs/dungeon_pool.json}, generated by tools/gen_dungeon_pool.py from SkyOcean's
 * pools (MIT) and the NEU item repo. Pure (Gson only). Its weights are not Hypixel's chances: they only decide which
 * filler goes past, never odds. Also the name table Croesus's "Contents" lines are priced through.
 */
public final class DungeonPool {

    public record Entry(Loot look, int weight) {}

    private final Map<String, List<Entry>> pools = new HashMap<>();
    private final Map<String, Loot> byKey = new HashMap<>();
    private final Map<String, String> nameToKey = new HashMap<>();

    public static DungeonPool parse(String json) {
        DungeonPool p = new DungeonPool();
        JsonObject root = JsonParser.parseString(json).getAsJsonObject().getAsJsonObject("pools");
        for (var floor : root.entrySet()) {
            for (var tier : floor.getValue().getAsJsonObject().entrySet()) {
                List<Entry> rows = new ArrayList<>();
                for (JsonElement e : tier.getValue().getAsJsonArray()) {
                    JsonObject o = e.getAsJsonObject();
                    String key = o.get("key").getAsString(), name = o.get("name").getAsString();
                    int colour = o.has("color") && o.get("color").getAsInt() != 0 ? o.get("color").getAsInt() : -1;
                    Loot look = new Loot(key, name, 1, false, str(o, "item"), str(o, "model"), str(o, "skin"),
                            o.has("glint") || o.has("book"), colour, null);
                    rows.add(new Entry(look, Math.max(1, o.get("weight").getAsInt())));
                    p.byKey.putIfAbsent(key, look);
                    p.nameToKey.putIfAbsent(name, key);
                    String book = PriceKeys.bookName(key);
                    if (book != null) p.nameToKey.putIfAbsent("Enchanted Book (" + book + ")", key);
                }
                p.pools.put(floor.getKey() + ":" + tier.getKey().toLowerCase(java.util.Locale.ROOT), rows);
            }
        }
        return p;
    }

    private static String str(JsonObject o, String k) {
        return o.has(k) ? o.get(k).getAsString() : null;
    }

    /**
     * The filler for a floor and chest. Only Obsidian and Bedrock have pools of their own; every other chest (and
     * the Entrance) borrows its floor's Obsidian pool, then Floor VII's - the reel only needs things to go past.
     */
    public List<Entry> pool(DungeonFloor floor, ChestTier tier) {
        String f = floor == null ? "F7" : floor.poolKey();
        List<Entry> l = pools.get(f + ":" + (tier == ChestTier.BEDROCK ? "bedrock" : "obsidian"));
        if (l == null || l.isEmpty()) l = pools.get(f + ":obsidian");
        if (l == null || l.isEmpty()) l = pools.get("F7:obsidian");
        return l == null ? List.of() : l;
    }

    /** How an item of this key looks, or null if the pool does not hold it. */
    public Loot look(String key) {
        return key == null ? null : byKey.get(key);
    }

    public Map<String, String> names() {
        return nameToKey;
    }
}
